namespace ghidra.app.plugin.match;



using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

public class ExactMnemonicsFunctionHasher : ExactInstructionsFunctionHasher {
	/* @SuppressWarnings("hiding") */
	public static readonly ExactMnemonicsFunctionHasher INSTANCE = new ExactMnemonicsFunctionHasher();

	private ExactMnemonicsFunctionHasher() {
		// use instance
	}

	/* @Override */
	protected long hash(TaskMonitor monitor, List<CodeUnit> units, int byteCount)
    {
		StringBuilder sb = new StringBuilder();
		foreach (CodeUnit codeUnit in units) {
			monitor.checkCancelled();

			if (codeUnit is Instruction) {
				Instruction inst = (Instruction) codeUnit;
				string mnemonic = inst.getMnemonicString();
				sb.append(mnemonic);
				// this is not allowed to be part of a mnemonic name, so it works as a separator
				sb.append("\n");
				sb.append(inst.getNumOperands());
			}
			else {
				try {
					byte[] bytes = codeUnit.getBytes();
					char[] chars = new char[bytes.length];
					for (int ii = 0; ii < bytes.length; ++ii) {
						chars[ii] = (char) bytes[ii];
					}
					sb.append(chars);
				}
				catch (MemoryAccessException e) {
					Msg.warn(this, "Could not get code unit bytes at " + codeUnit.getAddress());
					sb.append(codeUnit.getAddressString(true, true));
				}
			}
			// this is not allowed to be part of a mnemonic name, so it works as a separator
			sb.append("\n");
		}
		lock (digest) {
			digest.reset();
			digest.update(sb.toString().getBytes(), monitor);
			return digest.digestLong();
		}
	}
}
